"use strict";(globalThis.webpackChunkwebsite_docusaurus=globalThis.webpackChunkwebsite_docusaurus||[]).push([[6034],{8685(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/witweaver/","label":"WitWeaver","docId":"index","unlisted":false},{"type":"category","label":"Getting Started","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/witweaver/getting-started/quick-start","label":"Quick Start","docId":"getting-started/quick-start","unlisted":false},{"type":"link","href":"/witweaver/getting-started/project-structure","label":"Project Structure","docId":"getting-started/project-structure","unlisted":false},{"type":"link","href":"/witweaver/getting-started/troubleshooting","label":"Troubleshooting","docId":"getting-started/troubleshooting","unlisted":false}],"href":"/witweaver/getting-started/installation"},{"type":"category","label":"Core Systems","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/witweaver/core-systems/conversation-data","label":"Conversation Data","docId":"core-systems/conversation-data","unlisted":false},{"type":"link","href":"/witweaver/core-systems/conversation-container","label":"Conversation Container","docId":"core-systems/conversation-container","unlisted":false},{"type":"link","href":"/witweaver/core-systems/input-modes","label":"Input Modes","docId":"core-systems/input-modes","unlisted":false},{"type":"link","href":"/witweaver/core-systems/conversation-state","label":"Conversation State","docId":"core-systems/conversation-state","unlisted":false},{"type":"link","href":"/witweaver/core-systems/player-choices","label":"Player Choices","docId":"core-systems/player-choices","unlisted":false},{"type":"link","href":"/witweaver/core-systems/line-continuation","label":"Line Continuation","docId":"core-systems/line-continuation","unlisted":false}],"href":"/witweaver/core-systems/witweaver-component"},{"type":"link","href":"/witweaver/graph-editor/conversation-graph","label":"Graph Editor","docId":"graph-editor/conversation-graph","unlisted":false},{"type":"category","label":"Audio","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/witweaver/audio/unity-audio-setup","label":"Unity Audio Setup","docId":"audio/unity-audio-setup","unlisted":false},{"type":"link","href":"/witweaver/audio/fmod-integration","label":"FMOD Integration","docId":"audio/fmod-integration","unlisted":false},{"type":"link","href":"/witweaver/audio/wwise-integration","label":"Wwise Integration","docId":"audio/wwise-integration","unlisted":false},{"type":"link","href":"/witweaver/audio/custom-audio-provider","label":"Custom Audio Provider","docId":"audio/custom-audio-provider","unlisted":false}],"href":"/witweaver/audio/audio-overview"},{"type":"category","label":"YAML Reference","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/witweaver/yaml-reference/yaml-format","label":"YAML Format","docId":"yaml-reference/yaml-format","unlisted":false},{"type":"link","href":"/witweaver/yaml-reference/yaml-loading","label":"YAML Loading","docId":"yaml-reference/yaml-loading","unlisted":false}],"href":"/witweaver/yaml-reference/yaml-overview"},{"type":"category","label":"Characters","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/witweaver/characters/character-representations","label":"Character Representations","docId":"characters/character-representations","unlisted":false},{"type":"link","href":"/witweaver/characters/expressions","label":"Expressions","docId":"characters/expressions","unlisted":false},{"type":"link","href":"/witweaver/characters/animated-representations","label":"Animated Representations","docId":"characters/animated-representations","unlisted":false}],"href":"/witweaver/characters/character-profiles"},{"type":"category","label":"UI","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/witweaver/ui/sample-ui","label":"Sample UI","docId":"ui/sample-ui","unlisted":false},{"type":"link","href":"/witweaver/ui/building-a-ui","label":"Building a Custom UI","docId":"ui/building-a-ui","unlisted":false},{"type":"link","href":"/witweaver/ui/dialogue-history","label":"Dialogue History","docId":"ui/dialogue-history","unlisted":false}],"href":"/witweaver/ui/ui-foundation"},{"type":"category","label":"Dialogue Actions","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/witweaver/dialogue-actions/built-in-actions","label":"Built-in Actions","docId":"dialogue-actions/built-in-actions","unlisted":false},{"type":"link","href":"/witweaver/dialogue-actions/custom-actions","label":"Custom Actions","docId":"dialogue-actions/custom-actions","unlisted":false}],"href":"/witweaver/dialogue-actions/actions-overview"},{"type":"category","label":"Prefab Characters","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/witweaver/prefab-characters/canvas-ui","label":"Canvas UI","docId":"prefab-characters/canvas-ui","unlisted":false},{"type":"link","href":"/witweaver/prefab-characters/3d-ui","label":"3D UI","docId":"prefab-characters/3d-ui","unlisted":false},{"type":"link","href":"/witweaver/prefab-characters/presence-types","label":"Character Behaviours","docId":"prefab-characters/presence-types","unlisted":false},{"type":"link","href":"/witweaver/prefab-characters/display-components","label":"Display Components","docId":"prefab-characters/display-components","unlisted":false}],"href":"/witweaver/prefab-characters/overview"},{"type":"category","label":"Localization","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/witweaver/localization/adding-languages","label":"Adding Languages","docId":"localization/adding-languages","unlisted":false}],"href":"/witweaver/localization/localization-overview"},{"type":"category","label":"Save System","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/witweaver/save-system/save-manager","label":"Save Manager","docId":"save-system/save-manager","unlisted":false},{"type":"link","href":"/witweaver/save-system/conversation-save-manager","label":"Conversation Save Manager","docId":"save-system/conversation-save-manager","unlisted":false},{"type":"link","href":"/witweaver/save-system/variable-store","label":"Variable Store","docId":"save-system/variable-store","unlisted":false},{"type":"link","href":"/witweaver/save-system/save-providers","label":"Save Providers","docId":"save-system/save-providers","unlisted":false},{"type":"link","href":"/witweaver/save-system/snapshot-migration","label":"Snapshot Migration","docId":"save-system/snapshot-migration","unlisted":false}],"href":"/witweaver/save-system/save-system-overview"},{"type":"category","label":"Bulk Importing Conversations","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/witweaver/bulk-import/overview","label":"Bulk YAML Import","docId":"bulk-import/overview","unlisted":false}]},{"type":"link","href":"/witweaver/spreadsheet-workflow/overview","label":"Spreadsheet Workflow","docId":"spreadsheet-workflow/overview","unlisted":false},{"type":"link","href":"/witweaver/extending-witweaver","label":"Extending WitWeaver","docId":"extending-witweaver","unlisted":false},{"type":"link","href":"/witweaver/settings/witweaver-settings","label":"Settings","docId":"settings/witweaver-settings","unlisted":false}]},"docs":{"audio/audio-overview":{"id":"audio/audio-overview","title":"Audio Overview","description":"WitWeaver includes a full voice-line audio system that is designed to be backend-agnostic. You can play dialogue audio through Unity\'s built-in AudioSource, FMOD Studio, Wwise, or any custom audio engine \u2014 without changing your conversation data or YAML files.","sidebar":"tutorialSidebar"},"audio/custom-audio-provider":{"id":"audio/custom-audio-provider","title":"Custom Audio Provider","description":"If you are using an audio engine other than Unity AudioSource, FMOD, or Wwise \u2014 or if you need behaviour that the built-in providers do not cover \u2014 you can implement IWitWeaverAudioProvider yourself.","sidebar":"tutorialSidebar"},"audio/fmod-integration":{"id":"audio/fmod-integration","title":"FMOD Integration","description":"WitWeaver can drive voice dialogue through FMOD Studio by mapping each dialogue line to an FMOD event path. WitWeaver passes the event path to a provider component; the provider calls the FMOD API. This keeps the WitWeaver core assembly free of FMOD compile dependencies.","sidebar":"tutorialSidebar"},"audio/unity-audio-setup":{"id":"audio/unity-audio-setup","title":"Unity Audio Setup","description":"The UnityAudioSource backend is the quickest way to add voice audio to a WitWeaver conversation. Drag AudioClip assets directly into the manifest, and WitWeaver handles everything else \u2014 including automatically adding an AudioSource component to the runner\'s GameObject if one is not already present.","sidebar":"tutorialSidebar"},"audio/wwise-integration":{"id":"audio/wwise-integration","title":"Wwise Integration","description":"WitWeaver can drive voice dialogue through Audiokinetic Wwise by mapping each dialogue line to a Wwise event name. WitWeaver passes the event name to a provider component; the provider calls AkSoundEngine.PostEvent. This keeps the WitWeaver core assembly free of Wwise compile dependencies.","sidebar":"tutorialSidebar"},"bulk-import/overview":{"id":"bulk-import/overview","title":"Bulk YAML Import","description":"The Bulk Import window lets you scan a folder of YAML files, preview every conversation key found, and batch-create or batch-update WitWeaverConversationData ScriptableObject assets in one click. Each entry is processed independently \u2014 a parse error in one file never blocks the rest.","sidebar":"tutorialSidebar"},"characters/animated-representations":{"id":"characters/animated-representations","title":"Animated Representations","description":"An AnimatedCharacterRepresentationData asset lets a character\'s portrait and full body image play an animation instead of showing a single still sprite. The portrait can blink, breathe, talk, or loop any effect you can author, and it displays in the exact same portrait and slot images the static sprite representation uses.","sidebar":"tutorialSidebar"},"characters/character-profiles":{"id":"characters/character-profiles","title":"Character Profiles","description":"A WitWeaverCharacterProfileBaseData ScriptableObject represents one character in WitWeaver. It defines who the character is, what their display name and color are, and which visual representations they have available. Every character that speaks in a conversation must have a profile.","sidebar":"tutorialSidebar"},"characters/character-representations":{"id":"characters/character-representations","title":"Character Representations","description":"A character representation defines how a character looks for a given dialogue line: their sprite set, 3D prefab, or any other visual configuration. Representations are ScriptableObjects that extend CharacterRepresentationBase.","sidebar":"tutorialSidebar"},"characters/expressions":{"id":"characters/expressions","title":"Expressions","description":"Expressions are named emotional states (Happy, Angry, Surprised, Neutral) that control what a character looks like during a specific dialogue line. Each expression maps to a visual change: a different sprite, an animation, or any custom logic you provide.","sidebar":"tutorialSidebar"},"core-systems/conversation-container":{"id":"core-systems/conversation-container","title":"Conversation Container","description":"A ConversationContainer is a ScriptableObject that groups multiple conversations and defines a strategy for selecting which one to play. Rather than hard-coding a single conversation into a runner, you can point the runner at a container and let it decide at runtime, cycling through a pool of NPC greetings, playing a story sequence in order, or choosing dialogue based on weighted probability.","sidebar":"tutorialSidebar"},"core-systems/conversation-data":{"id":"core-systems/conversation-data","title":"Conversation Data","description":"WitWeaverConversationData is the ScriptableObject that represents a single conversation. It holds the compiled dialogue lines, the participant character profiles, localization data, and a stable identity GUID. It is the core data asset that the WitWeaver runner reads from at runtime.","sidebar":"tutorialSidebar"},"core-systems/conversation-state":{"id":"core-systems/conversation-state","title":"Conversation State","description":"WitWeaver tracks the lifecycle of a running conversation through the ConversationState enum, accessible at any time via the CurrentDialogueState property. Understanding state transitions is important for writing reliable UI code, integrating with other game systems, and avoiding common bugs like double-starting a conversation.","sidebar":"tutorialSidebar"},"core-systems/input-modes":{"id":"core-systems/input-modes","title":"Input Modes","description":"The Input field on the WitWeaver component determines what conversation (or group of conversations) plays when you call PlayConversation() with no arguments. Instead of a fixed reference to one conversation, this field accepts an IWitWeaverInput implementation, a small object that resolves a conversation at the moment PlayConversation() is called.","sidebar":"tutorialSidebar"},"core-systems/line-continuation":{"id":"core-systems/line-continuation","title":"Line Continuation","description":"After WitWeaver displays a dialogue line, it needs to know what to do next. Should it advance to the following line? End the conversation? Jump to a different conversation? Display a set of options for the player? The answer is controlled by the Line Continuation Mode, a field set on each line in the WitWeaverConversationData inspector, not in the YAML file itself.","sidebar":"tutorialSidebar"},"core-systems/player-choices":{"id":"core-systems/player-choices","title":"Player Choices","description":"When a dialogue line\'s continuation mode is set to PlayerChoice, WitWeaver pauses playback, hands a list of options to your UI, and waits for the player to make a selection. This page covers how to configure choice lines, what each field does, how to implement the UI coroutine that presents the options, and the edge cases you need to handle.","sidebar":"tutorialSidebar"},"core-systems/witweaver-component":{"id":"core-systems/witweaver-component","title":"WitWeaver Component","description":"The WitWeaver MonoBehaviour is the central piece of the runtime system. Attach it to a GameObject in your scene and it manages all conversation playback: loading dialogue data, advancing lines, running actions, firing events, and coordinating with the UI.","sidebar":"tutorialSidebar"},"dialogue-actions/actions-overview":{"id":"dialogue-actions/actions-overview","title":"Actions Overview","description":"Dialogue actions are the primary way to connect your dialogue to the rest of your game. They are ScriptableObject assets that run game logic in sync with individual lines - before the text appears, or after the player advances. Use them to trigger camera moves, spawn NPCs, play cutscenes, flip quest flags, update analytics, fade portraits in and out, or run any other code your game needs.","sidebar":"tutorialSidebar"},"dialogue-actions/built-in-actions":{"id":"dialogue-actions/built-in-actions","title":"Built-in Actions","description":"WitWeaver ships with six ready-to-use dialogue actions in the SampleActions folder. Each is a ScriptableObject you create as an asset and assign to dialogue lines in the inspector. Create them via Right-click in the Project panel \u2192 Create \u2192 WitWeaver \u2192 Actions \u2192 [Action Name].","sidebar":"tutorialSidebar"},"dialogue-actions/custom-actions":{"id":"dialogue-actions/custom-actions","title":"Custom Actions","description":"Custom dialogue actions let you run any game logic you want in sync with individual dialogue lines. They are ScriptableObject assets that extend BaseDialogueLineAction, so they are reusable across conversations, configurable per-asset in the inspector, and version-controlled like any other project asset.","sidebar":"tutorialSidebar"},"extending-witweaver":{"id":"extending-witweaver","title":"Extending WitWeaver","description":"WitWeaver is built top-to-bottom for extensibility. Every layer (dialogue actions, character visuals, character placement, UI display, and save storage) uses abstract base classes or interfaces that you replace or extend without touching the core package. This page maps every extension point and links to the detailed guide for each one.","sidebar":"tutorialSidebar"},"getting-started/installation":{"id":"getting-started/installation","title":"Installation","description":"This page walks you through installing WitWeaver into a Unity project via the Unity Package Manager, verifying the installation, and completing first-time setup.","sidebar":"tutorialSidebar"},"getting-started/project-structure":{"id":"getting-started/project-structure","title":"Project Structure","description":"This page explains how WitWeaver\'s files are organized inside the package itself, where to put your own project files, and how the framework\'s assembly structure works. Understanding this layout will help you avoid common file-placement mistakes and make it easier to navigate the codebase as your project grows.","sidebar":"tutorialSidebar"},"getting-started/quick-start":{"id":"getting-started/quick-start","title":"Quick Start","description":"This guide walks you through creating a simple \u201cHello World\u201d conversation from scratch. By the end you will have a fully wired WitWeaver setup running in a Unity scene, with console log output confirming that lines are advancing correctly. Adding a visible UI is covered in the UI Foundation page; this guide focuses on getting the core logic working first.","sidebar":"tutorialSidebar"},"getting-started/troubleshooting":{"id":"getting-started/troubleshooting","title":"Troubleshooting","description":"This page covers the most common problems encountered when setting up or using WitWeaver, along with their causes and fixes.","sidebar":"tutorialSidebar"},"graph-editor/conversation-graph":{"id":"graph-editor/conversation-graph","title":"Conversation Graph (Experimental)","description":"WitWeaver can author conversations visually as a node graph, built on Unity\'s Graph Toolkit (a built-in editor module in Unity 6000.4+). Each dialogue line is a node; wires define ordering, player choices, intra-conversation jumps, container branches, and endings \u2014 enabling nonlinear conversations without splitting content across multiple assets.","sidebar":"tutorialSidebar"},"index":{"id":"index","title":"WitWeaver","description":"WitWeaver is a Unity native dialogue framework for building the dialogue system your game deserves, in any genre, at any scale. Write your conversations in plain, readable YAML or spreadsheets, keep them in source control, and let WitWeaver compile them into runtime-ready Conversation ScriptableObjects.","sidebar":"tutorialSidebar"},"localization/adding-languages":{"id":"localization/adding-languages","title":"Adding Languages","description":"This page walks through the full process of adding a new language to your WitWeaver project, from registering the language in settings through testing it at runtime.","sidebar":"tutorialSidebar"},"localization/localization-overview":{"id":"localization/localization-overview","title":"Localization Overview","description":"WitWeaver has a native localization system built directly into the YAML dialogue format. No external localization packages are required. Every dialogue line carries its own translations as a map of language codes to text strings, and the runtime resolves the correct text for the active language at display time.","sidebar":"tutorialSidebar"},"prefab-characters/3d-ui":{"id":"prefab-characters/3d-ui","title":"3D UI","description":"WitWeaverSampleUI3D is the world-space dialogue UI. It handles dialogue text, speaker names, and choice buttons, but has no concept of character slots. Instead, it delegates all character placement to character behaviours \u2014 WitWeaverCharacterBehaviour ScriptableObjects that decide where each character goes and how long they stay there.","sidebar":"tutorialSidebar"},"prefab-characters/canvas-ui":{"id":"prefab-characters/canvas-ui","title":"Canvas UI","description":"WitWeaverSampleUICanvas is the canvas-space dialogue UI. It handles all dialogue text, speaker names, choice buttons, and character rendering \u2014 both sprites and prefabs \u2014 inside a Unity Canvas.","sidebar":"tutorialSidebar"},"prefab-characters/display-components":{"id":"prefab-characters/display-components","title":"Display Components","description":"A display component is a MonoBehaviour you add to a prefab character that translates WitWeaver expression calls into concrete visual changes. When the runner applies an expression to a character, the display component is what decides what actually happens on screen: an Animator state change, a blend shape transition, or a custom action.","sidebar":"tutorialSidebar"},"prefab-characters/overview":{"id":"prefab-characters/overview","title":"Overview","description":"WitWeaver supports 3D prefab characters in addition to flat sprites. Where a sprite representation stores a set of images, a prefab representation stores a reference to a Unity prefab. The prefab is a real GameObject that can be spawned into a scene, driven by an Animator, and fully integrated into your world.","sidebar":"tutorialSidebar"},"prefab-characters/presence-types":{"id":"prefab-characters/presence-types","title":"Character Behaviours","description":"A character behaviour is a ScriptableObject that decides where 3D prefab characters are positioned during a conversation and how long they remain in the scene. The 3D UI calls into the behaviour at conversation start, per line, and at conversation end \u2014 the behaviour handles the rest.","sidebar":"tutorialSidebar"},"save-system/conversation-save-manager":{"id":"save-system/conversation-save-manager","title":"Conversation Save Manager","description":"WitWeaverConversationSaveManager is a MonoBehaviour that sits alongside your WitWeaver component on a scene GameObject. It tracks progress for one conversation (or one entry in a ConversationContainer) and feeds the resume context back into the runner automatically when the conversation starts.","sidebar":"tutorialSidebar"},"save-system/save-manager":{"id":"save-system/save-manager","title":"Save Manager","description":"WitWeaverSaveManager is the central hub of the save system. It owns the active save provider, manages save slots, assembles the full game snapshot, and distributes restored snapshots to all registered conversation savers.","sidebar":"tutorialSidebar"},"save-system/save-providers":{"id":"save-system/save-providers","title":"Save Providers","description":"A save provider handles the actual reading and writing of save data to a storage backend. The provider is decoupled from the rest of the save system behind the IWitWeaverSaveProvider interface, so you can swap storage backends without changing any gameplay code.","sidebar":"tutorialSidebar"},"save-system/save-system-overview":{"id":"save-system/save-system-overview","title":"Save System Overview","description":"The WitWeaver Save System persists conversation progress and game state across play sessions. It is a separate, optional module; the core WitWeaver runner has no hard dependency on it. Drop it in when your project needs durable progress tracking.","sidebar":"tutorialSidebar"},"save-system/snapshot-migration":{"id":"save-system/snapshot-migration","title":"Snapshot Migration","description":"As you develop and ship updates to your game, the structure of your save data may change: new fields added, variables renamed, conversation GUIDs regenerated, or scope assignments altered. WitWeaverSnapshotMigrator ensures that save files created with an older version of the schema can still be loaded correctly after an update.","sidebar":"tutorialSidebar"},"save-system/variable-store":{"id":"save-system/variable-store","title":"Variable Store","description":"WitWeaverVariableStore is a ScriptableObject that stores typed, scoped key-value pairs: a lightweight runtime database for gameplay state that dialogue can read and write. It is the bridge between what happens in a conversation and the rest of your game.","sidebar":"tutorialSidebar"},"settings/witweaver-settings":{"id":"settings/witweaver-settings","title":"WitWeaver Settings","description":"WitWeaverSettings is a sealed ScriptableObject that controls global WitWeaver configuration. It is the single configuration file for the entire framework. Language support, YAML source resolution order, save system keys, debug logging, and history renderer profiles are all managed here.","sidebar":"tutorialSidebar"},"spreadsheet-workflow/overview":{"id":"spreadsheet-workflow/overview","title":"Excel Workflow","description":"WitWeaver supports authoring dialogue in .xlsx spreadsheets as an alternative to hand-editing YAML. The spreadsheet is the source of truth: every time you save the file in Excel (or any spreadsheet editor), Unity reimports it, generates LineIDs, writes them back to the .xlsx, and rebuilds the WitWeaverConversationData ScriptableObject automatically.","sidebar":"tutorialSidebar"},"ui/building-a-ui":{"id":"ui/building-a-ui","title":"Building a Custom UI","description":"WitWeaver includes a ready-made sample UI in the Samples package that demonstrates all of these patterns in a working scene. If you prefer a hands-on starting point over building from scratch, import the Sample UI first and read its code alongside this guide.","sidebar":"tutorialSidebar"},"ui/dialogue-history":{"id":"ui/dialogue-history","title":"Dialogue History","description":"What Is Dialogue History?","sidebar":"tutorialSidebar"},"ui/sample-ui":{"id":"ui/sample-ui","title":"Sample UI","description":"WitWeaver includes a fully working dialogue UI in its Samples package. If you want a real, working display layer to learn from or build on top of rather than creating one from scratch, this is the fastest way to get started.","sidebar":"tutorialSidebar"},"ui/ui-foundation":{"id":"ui/ui-foundation","title":"UI Foundation","description":"What is WitWeaverUIFoundation?","sidebar":"tutorialSidebar"},"yaml-reference/yaml-format":{"id":"yaml-reference/yaml-format","title":"YAML Format","description":"This page is the complete field reference for WitWeaver\'s YAML dialogue format. Every supported field is documented here with an explanation of its purpose, whether it is required, and examples showing correct usage.","sidebar":"tutorialSidebar"},"yaml-reference/yaml-loading":{"id":"yaml-reference/yaml-loading","title":"YAML Loading","description":"At runtime, WitWeaver needs to find the YAML text for a conversation before it can parse and play it. The WitWeaverYamlLoader handles this by trying up to four different sources in a configurable priority order. This page explains each source, when to use it, how to configure the load order, and the three loading APIs available to your code.","sidebar":"tutorialSidebar"},"yaml-reference/yaml-overview":{"id":"yaml-reference/yaml-overview","title":"YAML Overview","description":"WitWeaver authors dialogue in YAML - a plain-text format that any editor can open, any version-control system can track, and any writer can read without prior programming experience. This page explains what YAML is, why WitWeaver uses it, and the practical rules you need to follow to write valid dialogue files.","sidebar":"tutorialSidebar"}}}}')}}]);